//! The builtin surface, checked against the pinned reference's own inventory.
//!
//! The builtin tools have no OpenAPI document, so `tests/fixtures/builtin/oracle.json` IS their
//! contract: every mounted tool's wire name, description and input schema, and the per-caller
//! scope sets, generated by `parity/tools/gen_builtin_fixtures.py` running the reference's own
//! FastMCP server and scope table. A tool that is renamed, re-schematised or dropped, or a scope
//! that grants the wrong set, fails here instead of reaching a caller.

mod support;

use serde_json::Value;

use mcp_server_rs::builtin::BuiltinProvider;
use mcp_server_rs::builtin::scope::{BuiltinCaller, CallerKind};
use support::Fixture;

/// The family namespaces this test compares. The reference's builtin server also mounts the 20
/// `builder_*` tools; that family needs the installed builder service and is asserted against
/// the same fixture by `tests/builtin_builder.rs`.
const FAMILIES: [&str; 9] = [
    "crm",
    "order",
    "delivery",
    "rules",
    "procedures",
    "faq",
    "legal",
    "research",
    "web",
];

/// One listed tool, flattened to the three facts the fixture pins.
struct Listed {
    name: String,
    description: Option<String>,
    input_schema: Value,
}

fn oracle() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/builtin/oracle.json"
    );
    let text = std::fs::read_to_string(path).expect("the builtin fixture file exists");
    serde_json::from_str(&text).expect("the builtin fixture file is JSON")
}

fn family(name: &str) -> bool {
    let namespace = name.split('_').next().unwrap_or_default();
    FAMILIES.contains(&namespace)
}

/// The fixture is generated with `LEGAL_UOKIK_ENABLED` on; a test process that does not set it
/// builds the registry with the two UOKiK tools absent, and `the_uokik_gate_hides_exactly_two_tools`
/// proves that is the only difference. The comparisons below use the gated set.
fn gated(name: &str) -> bool {
    name != "legal_uokik_search" && name != "legal_uokik_document"
}

/// Tools this port adds beyond the pinned reference's inventory. The fixture is the reference's
/// own `tools/list` output, so an extension is filtered out of the reference comparison and
/// asserted directly by `tests/builtin_carebus.rs` instead of being written into the fixture.
const EXTENSIONS: [&str; 3] = ["early_access_request", "ebook_request", "faq_search"];

fn extension(name: &str) -> bool {
    !EXTENSIONS.contains(&name)
}

fn caller(scope: &str) -> BuiltinCaller {
    BuiltinCaller {
        kind: CallerKind::KeycloakService,
        subject: format!("svc:{scope}"),
        scope: scope.to_owned(),
        tenant_id: None,
        license_id: None,
        strata_token: None,
    }
}

fn listing(provider: &BuiltinProvider, scope: &str) -> Vec<Listed> {
    provider
        .list(&caller(scope))
        .into_iter()
        .map(|tool| Listed {
            name: tool.name.to_string(),
            description: tool.description.as_ref().map(|text| text.to_string()),
            input_schema: Value::Object((*tool.input_schema).clone()),
        })
        .filter(|tool| extension(&tool.name))
        .collect()
}

fn names(listed: &[Listed]) -> Vec<String> {
    let mut names: Vec<String> = listed.iter().map(|tool| tool.name.clone()).collect();
    names.sort();
    names
}

#[tokio::test]
async fn every_family_tool_matches_the_references_name_description_and_schema() {
    let fixture = Fixture::new().await;
    let provider = mcp_server_rs::builtin::create(fixture.pool.clone(), None);
    // The union of every scope is the whole family surface: the care-bus licence carries the
    // reference's widest set (`licence:care-bus` = care-bus + researcher).
    let listed = listing(&provider, "licence:care-bus");
    let document = oracle();
    let fixtures: Vec<&Value> = document["tools"]
        .as_array()
        .expect("tools")
        .iter()
        .filter(|tool| family(tool["name"].as_str().expect("name")))
        .filter(|tool| gated(tool["name"].as_str().expect("name")))
        .collect();
    assert_eq!(
        listed.len(),
        fixtures.len(),
        "the port registers a different number of family tools: {:?}",
        names(&listed)
    );
    for expected in fixtures {
        let name = expected["name"].as_str().expect("name");
        let found = listed
            .iter()
            .find(|tool| tool.name == name)
            .unwrap_or_else(|| panic!("{name} is missing from the port"));
        assert_eq!(
            found.input_schema, expected["input_schema"],
            "{name}: the input schema differs from the reference's"
        );
        assert_eq!(
            found.description.as_deref(),
            expected["description"].as_str(),
            "{name}: the description differs from the reference's"
        );
    }
    fixture.finish().await;
}

#[tokio::test]
async fn every_scope_grants_exactly_the_references_set() {
    let fixture = Fixture::new().await;
    let provider = mcp_server_rs::builtin::create(fixture.pool.clone(), None);
    for (scope, expected) in oracle()["scopes"].as_object().expect("scopes") {
        let mut expected: Vec<String> = expected
            .as_array()
            .expect("scope list")
            .iter()
            .map(|name| name.as_str().expect("name"))
            .filter(|name| family(name) && gated(name))
            .map(str::to_owned)
            .collect();
        expected.sort();
        assert_eq!(
            names(&listing(&provider, scope)),
            expected,
            "{scope} grants a different set"
        );
    }
    fixture.finish().await;
}

#[tokio::test]
async fn the_uokik_gate_hides_exactly_two_tools() {
    // The fixture is generated with `LEGAL_UOKIK_ENABLED` on; this process builds the registry
    // with it off, which must remove exactly the two UOKiK tools and nothing else.
    let fixture = Fixture::new().await;
    let provider = mcp_server_rs::builtin::create(fixture.pool.clone(), None);
    let listed = names(&listing(&provider, "carebus-researcher"));
    assert!(!listed.iter().any(|name| name == "legal_uokik_search"));
    assert!(!listed.iter().any(|name| name == "legal_uokik_document"));
    // 21 in the fixture (UOKiK on) minus the two gated tools.
    assert_eq!(listed.len(), 19, "{listed:?}");
    fixture.finish().await;
}
